/**
 * Накопительные счётчики за всё время — «стаж охотника».
 * Нужны для достижений с пожизненными условиями (5000 зёрен, 25 голубей,
 * 10 лихорадок, 50 сосок…). Хранятся в localStorage одним JSON-объектом.
 *
 * Пишет лениво: изменения копятся в памяти и сбрасываются на диск
 * не чаще раза в 1.5 секунды (или принудительно flushLife()),
 * чтобы частые события (каждое зёрнышко) не дёргали localStorage.
 */

export interface LifeStats {
  /** Зёрен сдано в стаканчик за всё время */
  grains: number
  /** Золотых зёрен за всё время */
  golden: number
  /** Повержено голубей-воришек */
  pigeons: number
  /** Ловушек-мин (со шком) — «горький опыт» */
  mines: number
  /** ЛИХОРАДОК пережито */
  fevers: number
  /** Забегов начато */
  runs: number
  /** Уровней пройдено за всё время (v0.0.60: триггер пуша о поддержке каждые 20 уровней) */
  levelsPassed: number
  /** Проклятий из сундучков взято */
  curse: number
  /** Бонусов из сундучков взято */
  bonus: number
  /** Сосок 🍼 поймано (перк «Соски-малышки») */
  nipples: number
  /** Подарочных коробок 🎁 поймано за всё время (0.0.41) */
  gifts: number
  /** Чистых секунд в игре (только геймплей, паузы не считаются) */
  secs: number
  /** Сколько раз открывали сайт на этом устройстве */
  visits: number
  /** Уровней пройдено «без мин и без краж» за всё время */
  perfects: number
  /** Суммарный счёт за все забеги (только положительные дельты) */
  score: number
  /** Больших попкорнин поймано за всё время (поле) */
  bigCaught: number
  /** Из них по сортам — ачивка «Полное меню» нарезки и «Виноградный магнат» */
  bigCaramel: number
  bigCherry: number
  bigGrape: number
  /** Побед над боссом МАЛЫШЕМ за всё время */
  bossKills: number
  /** Побед над ЛЬВОМ за всё время (v0.0.33) */
  bossLionKills: number
  /** Побед над КУНИЦЕЙ ЛАНОЙ за всё время (v0.0.33) */
  bossMartenKills: number
  /** Побед над МЕГА-ГОЛУБЕМ за всё время (v0.0.38) */
  bossPigeonKills: number
  /** Побед над ЦЫГАНСКОЙ РУКОЙ за всё время (v0.0.39) */
  bossGypsyKills: number
  /** Нарезок по сортам за всё время — ачивка «Полное меню» */
  sliceCaramel: number
  sliceCherry: number
  sliceGrape: number
}

export const LIFE_KEY = 'popcorn-lifestats'

const DEFAULT_LIFE: LifeStats = {
  grains: 0,
  golden: 0,
  pigeons: 0,
  mines: 0,
  fevers: 0,
  runs: 0,
  levelsPassed: 0,
  curse: 0,
  bonus: 0,
  nipples: 0,
  gifts: 0,
  secs: 0,
  visits: 0,
  perfects: 0,
  score: 0,
  bigCaught: 0,
  bigCaramel: 0,
  bigCherry: 0,
  bigGrape: 0,
  bossKills: 0,
  bossLionKills: 0,
  bossMartenKills: 0,
  bossPigeonKills: 0,
  bossGypsyKills: 0,
  sliceCaramel: 0,
  sliceCherry: 0,
  sliceGrape: 0,
}

/** Живой объект в памяти — единый источник между кадрами */
let cache: LifeStats | null = null
let dirty = false
let flushTimer: number | null = null

function parseLife(raw: string | null | undefined): LifeStats {
  try {
    const v: unknown = JSON.parse(raw ?? '')
    if (v && typeof v === 'object') {
      const o = v as Record<string, unknown>
      const out = { ...DEFAULT_LIFE }
      for (const k of Object.keys(DEFAULT_LIFE) as Array<keyof LifeStats>) {
        const n = Number(o[k])
        if (Number.isFinite(n) && n > 0) out[k] = Math.floor(n)
      }
      return out
    }
  } catch {
    /* пусто — дефолты */
  }
  return { ...DEFAULT_LIFE }
}

/** Текущие счётчики (память → localStorage при первом обращении) */
export function getLife(): LifeStats {
  if (cache) return cache
  if (typeof window === 'undefined') return { ...DEFAULT_LIFE }
  try {
    cache = parseLife(window.localStorage.getItem(LIFE_KEY))
  } catch {
    cache = { ...DEFAULT_LIFE }
  }
  return cache
}

/** Прибавить дельты (только положительные поля учитываются) */
export function addLife(patch: Partial<LifeStats>): LifeStats {
  const cur = getLife()
  for (const k of Object.keys(patch) as Array<keyof LifeStats>) {
    const d = patch[k]
    if (typeof d === 'number' && d > 0) cur[k] += Math.floor(d)
  }
  dirty = true
  scheduleFlush()
  return cur
}

function scheduleFlush(): void {
  if (flushTimer !== null || typeof window === 'undefined') return
  flushTimer = window.setTimeout(() => {
    flushTimer = null
    flushLife()
  }, 1500)
}

/** Сбросить накопленное на диск (по таймеру, при уходе со страницы) */
export function flushLife(): void {
  if (!dirty || !cache || typeof window === 'undefined') return
  try {
    window.localStorage.setItem(LIFE_KEY, JSON.stringify(cache))
  } catch {
    /* приватный режим — молча */
  }
  dirty = false
}
